using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class DayNightLiveAudit{static DayNightLiveAudit(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling||!File.Exists("DayNightLiveAudit.request"))return;File.Delete("DayNightLiveAudit.request");var cs=Resources.FindObjectsOfTypeAll<CityDayNightController>().Where(c=>c.gameObject.scene.IsValid()).ToArray();var log=cs.Select(c=>"Controller="+c.name+" scene="+c.gameObject.scene.path+" active="+c.isActiveAndEnabled+" night="+c.IsNight+" blend="+c.NightBlend+" transitioning="+c.IsTransitioning+" sun="+(c.sun?c.sun.name:"NULL")+" presets="+(c.presets?c.presets.name:"NULL")+" duration="+c.transitionSeconds+" dayAmount="+(c.presets?c.presets.day.nightAmount:-1)+" nightAmount="+(c.presets?c.presets.night.nightAmount:-1)).ToList();log.Add("GlobalNight="+Shader.GetGlobalFloat("_GangstarNight")+" playing="+Application.isPlaying+" activeScene="+SceneManager.GetActiveScene().path);foreach(SceneView v in SceneView.sceneViews)log.Add("SceneView="+v.titleContent.text+" sceneLighting="+v.sceneLighting+" effects="+v.sceneViewState.showImageEffects);File.WriteAllLines("FinalEnvironmentRoadReview/DayNightLiveAudit.txt",log);}}
